  t["$: hacen falta $"] = "$: you need $";
  t["$: hay menos de dos muestras por oscilación."] = "$: there are fewer than two samples per oscillation.";
  t["$: hay un nivel de población cuyo crecimiento la compensa, y la población se queda ahí."] = "$: there is a population level whose growth makes up for it, and the population stays there.";
  t["$: hay un salto"] = "$: there is a jump";
  t["$: iguales, como tiene que ser en el óptimo."] = "$: equal, as they must be at the optimum.";
  t["$: invertir el condicionamiento cambia el resultado."] = "$: inverting the conditioning changes the result.";
  t["$: la casilla entre el total de la columna de $Z$."] = "$: the cell over the total of the column of $Z$.";
  t["$: la casilla entre el total de la fila de $C$."] = "$: the cell over the total of the row of $C$.";
  t["$: la lista ha dado "] = "$: the list has gone round ";
  t["$: la parábola solo toca el eje y no lo cruza. El signo es siempre el de $a$ salvo en ese punto."] = "$: the parabola only touches the axis and does not cross it. The sign is always that of $a$ except at that point.";
  t["$: la recta es $y = "] = "$: the line is $y = ";
  t["$: la sucesión oscila"] = "$: the sequence oscillates";
  t["$: la tangente es $y = "] = "$: the tangent is $y = ";
  t["$: las bandas $f_c \\pm k f_m$ son múltiplos de $"] = "$: the sidebands $f_c \\pm k f_m$ are multiples of $";
  t["$: los dos positivos"] = "$: both positive";
  t["$: los extremos no coinciden"] = "$: the endpoints do not agree";
  t["$: los extremos no valen lo mismo"] = "$: the endpoints are not equal";
  t["$: los sucesos serían independientes."] = "$: the events would be independent.";
  t["$: mucho menos de lo que parece, porque los sanos son muchísimos más que los enfermos."] = "$: far less than it seems, because the healthy are vastly more numerous than the ill.";
  t["$: negativo antes, positivo después."] = "$: negative before, positive after.";
  t["$: no se rechaza $H_0$. Los datos no permiten afirmar que haya aumentado."] = "$: $H_0$ is not rejected. The data do not allow the claim that it has risen.";
  t["$: para esos valores no hay inversa."] = "$: for those values there is no inverse.";
  t["$: pasa el "] = "$: through goes ";
  t["$: predice $"] = "$: it predicts $";
  t["$: queda el "] = "$: there is left ";
