  t["<strong style=\"color:var(--bad)\">Con a = b la raíz es doble:</strong> hace falta otra forma de descomponer, con $\\frac{A}{x-a} + \\frac{B}{(x-a)^2}$."] = "<strong style=\"color:var(--bad)\">With a = b the root is double:</strong> another form of decomposition is needed, with $\\frac{A}{x-a} + \\frac{B}{(x-a)^2}$.";
  t["<strong style=\"color:var(--bad)\">Dependientes</strong>: uno es múltiplo del otro, así que solo generan una <strong>recta</strong>. Dimensión 1."] = "<strong style=\"color:var(--bad)\">Dependent</strong>: one is a multiple of the other, so they span only a <strong>line</strong>. Dimension 1.";
  t["<strong style=\"color:var(--bad)\">Determinante cero: el plano se aplasta sobre una recta.</strong> La aplicación pierde una dimensión, no tiene inversa y su núcleo no es solo el origen."] = "<strong style=\"color:var(--bad)\">Determinant zero: the plane is flattened onto a line.</strong> The map loses a dimension, has no inverse and its kernel is more than just the origin.";
  t["<strong style=\"color:var(--bad)\">Imposible</strong>, sin necesidad de probar ninguna colocación: los colores no están equilibrados."] = "<strong style=\"color:var(--bad)\">Impossible</strong>, with no need to try any arrangement: the colours are not balanced.";
  t["<strong style=\"color:var(--bad)\">Incompatible</strong>: rectas paralelas. No hay ningún punto que cumpla las dos."] = "<strong style=\"color:var(--bad)\">Inconsistent</strong>: parallel lines. There is no point satisfying both.";
  t["<strong style=\"color:var(--bad)\">Insostenible:</strong> se pesca más de lo que la población puede reponer"] = "<strong style=\"color:var(--bad)\">Unsustainable:</strong> more is fished than the population can replace";
