  t["<strong style=\"color:var(--bad)\">demasiado grande</strong>: los pasos se pasan de largo y la trayectoria oscila o se dispara."] = "<strong style=\"color:var(--bad)\">too large</strong>: the steps overshoot and the path oscillates or blows up.";
