  t["<strong style=\"color:var(--bad)\">no es cota</strong>: hay elementos a su derecha"] = "<strong style=\"color:var(--bad)\">it is not a bound</strong>: there are elements to its right";
  t["<strong style=\"color:var(--c5)\">Has vuelto al punto de partida, pero la flecha apunta al lado contrario.</strong> Hace falta dar <em>dos</em> vueltas para recuperar la orientación original: por eso la banda tiene una sola cara."] = "<strong style=\"color:var(--c5)\">You have returned to the starting point, but the arrow points the other way.</strong> It takes <em>two</em> turns to recover the original orientation: that is why the band has a single side.";
  t["<strong style=\"color:var(--ok)\">Alineados: es un autovector, con autovalor λ = "] = "<strong style=\"color:var(--ok)\">Lined up: it is an eigenvector, with eigenvalue λ = ";
