  t["<strong style=\"color:var(--ok)\">Realimentación negativa</strong> ($K>0$): la corrección se opone a la desviación, que se va apagando."] = "<strong style=\"color:var(--ok)\">Negative feedback</strong> ($K>0$): the correction opposes the deviation, which dies away.";
  t["<strong style=\"color:var(--ok)\">Se estabiliza.</strong> La corrección llega a tiempo de servir de algo."] = "<strong style=\"color:var(--ok)\">It settles.</strong> The correction arrives in time to be of some use.";
  t["<strong style=\"color:var(--ok)\">Sostenible:</strong> la población se estabiliza en unos $"] = "<strong style=\"color:var(--ok)\">Sustainable:</strong> the population settles at about $";
