  t["<strong style=\"color:var(--ok)\">Sí, empezando en uno de los dos vértices impares y acabando en el otro.</strong>"] = "<strong style=\"color:var(--ok)\">Yes, starting at one of the two odd vertices and finishing at the other.</strong>";
  t["<strong style=\"color:var(--ok)\">Sí, y además se puede terminar donde se empezó</strong> (recorrido cerrado)."] = "<strong style=\"color:var(--ok)\">Yes, and you can also finish where you started</strong> (a closed trail).";
  t["<strong style=\"color:var(--ok)\">dos soluciones</strong>: $x_1 = "] = "<strong style=\"color:var(--ok)\">two solutions</strong>: $x_1 = ";
  t["<strong style=\"color:var(--ok)\">primo</strong>"] = "<strong style=\"color:var(--ok)\">prime</strong>";
