  t["Calcula $T = \\dfrac{G}{1 + GH}$ con la $G$ de antes y con la de después."] = "Compute $T = \\dfrac{G}{1 + GH}$ with the earlier $G$ and with the later one.";
  t["Calcula $\\Delta$. ¿Cuántas soluciones va a haber?"] = "Work out $\\Delta$. How many solutions will there be?";
  t["Calcula $\\cos$ y $\\operatorname{sen}$ de $0$, $\\pi/2$, $\\pi$ y $3\\pi/2$."] = "Compute $\\cos$ and $\\sin$ of $0$, $\\pi/2$, $\\pi$ and $3\\pi/2$.";
  t["Calcula $\\dbinom{"] = "Work out $\\dbinom{";
  t["Calcula $\\det "] = "Work out $\\det ";
  t["Calcula $\\det A$ con $k$ dentro."] = "Work out $\\det A$ with $k$ inside.";
