  t["F_n = \\frac{\\varphi^n - \\psi^n}{\\sqrt 5}, \\qquad \\varphi = \\frac{1 + \\sqrt 5}{2} \\approx 1{,}618, \\qquad \\psi = \\frac{1 - \\sqrt 5}{2} \\approx -0{,}618"] = "F_n = \\frac{\\varphi^n - \\psi^n}{\\sqrt 5}, \\qquad \\varphi = \\frac{1 + \\sqrt 5}{2} \\approx 1{.}618, \\qquad \\psi = \\frac{1 - \\sqrt 5}{2} \\approx -0{.}618";
