  t["Halla el ángulo"] = "Find the angle";
  t["Halla el ángulo entre $0^\\circ$ y $360^\\circ$ que tiene las mismas razones "] = "Find the angle between $0^\\circ$ and $360^\\circ$ having the same trigonometric ";
