  t["Halla la pendiente de una recta "] = "Find the gradient of a line ";
  t["Halla la primitiva y aplica Barrow: $F(b) - F(a)$. La constante $C$ se cancela, así que no hace falta."] = "Find the antiderivative and apply Barrow: $F(b) - F(a)$. The constant $C$ cancels, so it is not needed.";
  t["Halla la proyección ortogonal $Q$ de $P$ sobre $\\pi$."] = "Find the orthogonal projection $Q$ of $P$ onto $\\pi$.";
  t["Halla la proyección ortogonal $Q$ de $P$ sobre $r$."] = "Find the orthogonal projection $Q$ of $P$ onto $r$.";
  t["Halla la recta de regresión de $Y$ sobre $X$ y úsala para predecir el valor de $y$ "] = "Find the regression line of $Y$ on $X$ and use it to predict the value of $y$ ";
  t["Halla la recta tangente a $f(x) = "] = "Find the tangent line to $f(x) = ";
  t["Halla las asíntotas vertical y horizontal de "] = "Find the vertical and horizontal asymptotes of ";
