  t["Resuelve $e^{-t/\\tau} = 1/2$: sale $t = \\tau\\ln 2$. Despeja $\\tau$."] = "Solve $e^{-t/\\tau} = 1/2$: out comes $t = \\tau\\ln 2$. Solve for $\\tau$.";
  t["Resuelve $e^{-t/\\tau} = p$ tomando logaritmos: $t = -\\tau\\ln p$, con $p$ en tanto por uno."] = "Solve $e^{-t/\\tau} = p$ by taking logarithms: $t = -\\tau\\ln p$, with $p$ as a fraction of one.";
